/**
 * BOBALAB wordmark (DECISIONS D-13 item 2): "BOBALAB" in Archivo condensed bold
 * (wdth 68, wght 700) with the first O replaced by the pearl, the same matte
 * tapioca pearl that ends each lane of Fig. 1. Fully outlined inline SVG: the
 * glyph outlines come from wordmark-geometry.ts (generated by
 * scripts/brand/build-wordmark.py from the self-hosted Archivo file), so it
 * never waits for web fonts. One colour (currentColor): ink on paper in light
 * mode, light ink on the dark paper in dark mode, CanvasText in forced colours.
 */
import { WORDMARK } from "./wordmark-geometry";

const [, , VW, VH] = WORDMARK.viewBox;
const P = WORDMARK.pearl;

export interface WordmarkProps {
  /** Rendered height in CSS units (width follows the aspect ratio). */
  height?: string | number;
  /** @deprecated No effect: the pearl has no highlight to hide any more. */
  small?: boolean;
  className?: string;
  /** Accessible name; pass "" when the visible text next to it already names the lab. */
  title?: string;
}

export function Wordmark({ height = "2rem", className, title = "BOBALAB" }: WordmarkProps) {
  const cls = ["bl-wordmark", className].filter(Boolean).join(" ");
  const a11y = title ? { role: "img", "aria-label": title } : { "aria-hidden": true as const };
  return (
    <svg
      className={cls}
      viewBox={`0 0 ${VW} ${VH}`}
      style={{ height, width: "auto", aspectRatio: `${VW} / ${VH}` }}
      xmlns="http://www.w3.org/2000/svg"
      focusable="false"
      {...a11y}
    >
      {title ? <title>{title}</title> : null}
      <g fill="currentColor">
        {WORDMARK.boba.slice(0, 1).map((d, i) => (
          <path key={`b${i}`} d={d} />
        ))}
        <circle className="bl-wordmark__pearl-o" cx={P.cx} cy={P.cy} r={P.r} />
        {WORDMARK.boba.slice(1).map((d, i) => (
          <path key={`o${i}`} d={d} />
        ))}
        {WORDMARK.lab.map((d, i) => (
          <path key={`l${i}`} d={d} />
        ))}
      </g>
    </svg>
  );
}

/** Wordmark plus descriptor lockup ("Berkeley Operations and Behavioral Analytics Lab"). */
export function WordmarkLockup({
  descriptor,
  height = "2.5rem",
}: {
  descriptor: string;
  height?: string;
}) {
  return (
    <span className="bl-lockup">
      <Wordmark height={height} title="BOBALAB" />
      <span className="bl-lockup__descriptor">{descriptor}</span>
    </span>
  );
}
